  update catalogo_productos c set sinonimos=(select array_agg(distinct x) from unnest(c.sinonimos || n.sinonimos) x) from _nuevos n
    where lower(c.nombre)=lower(n.nombre) and c.activo and (c.sucursal_id=wp or c.sucursal_id is null);
  insert into catalogo_productos(nombre, sinonimos, categoria_id, unidad_default, sucursal_id, activo)
    select n.nombre, n.sinonimos, (select g.id from categorias_gasto g where g.nombre=n.categoria and (g.sucursal_id is null or g.sucursal_id=wp) limit 1), n.unidad, wp, true from _nuevos n
    where not exists (select 1 from catalogo_productos c where lower(c.nombre)=lower(n.nombre) and c.activo and (c.sucursal_id=wp or c.sucursal_id is null));
end $$;
